pm.test('signin accepts a submission with email and password, per the canonical spec (KNOWN DRIFT: the live API requires \'email_or_username\', not \'email\' - see postman/README.md)', function () {
  pm.expect(pm.response.code, 'expected the submission to proceed rather than be rejected outright').to.not.equal(401);
});

pm.test('signin succeeds and returns a token for a spec-compliant submission (KNOWN DRIFT: see postman/README.md)', function () {
  pm.expect(pm.response.code).to.equal(200);
  const body = pm.response.json();
  pm.expect(body).to.have.property('token');
});

pm.test('signin rejects a submission with no email and names the email field (KNOWN DRIFT: see postman/README.md)', function () {
  pm.expect(pm.response.code).to.equal(401);
  const body = pm.response.json();
  pm.expect(body, 'response should name the email field').to.have.property('email');
});

pm.test('signin rejects a submission with no password and names the password field', function () {
  pm.expect(pm.response.code).to.equal(401);
  const body = pm.response.json();
  pm.expect(body).to.have.property('password');
});

pm.test('a rejected signin response never contains the submitted password', function () {
  pm.expect(pm.response.text()).to.not.include('Passw0rd1');
});

pm.test('a rejected signin returns HTTP 401', function () {
  pm.expect(pm.response.code).to.equal(401);
});
